-- What supabase/designer_period.sql does, tried inside the rolled-back
-- transaction of a dry run: nothing here is kept.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/designer_period.sql --dry --try=tools/designer_period_try.sql --table=model_opens
--
-- After the live files (designers.sql, replies.sql, people.sql, builds.sql,
-- lists.sql), which the project has. Made-up accounts, made and gone with the
-- transaction: Ada designs 50 models (and one taken out, one unpublished),
-- Bob and Cy like, keep, comment on and remix them, Bob has a model of his
-- own. Every model a test model. Times are set by hand: inside one
-- transaction now() never moves. Each statement is on one line: the dry run
-- splits at a semicolon that ends a line.
--
-- Every number designer_period gives is held against a count written here
-- plainly from the rows (pg_temp.direct), for each model, each kind, the last
-- 30 days, the 30 before, each of the 8 weeks and in all, and comments
-- against designer_said itself: the mismatches must be 0.
-- First, on the real tables before anything is made here: the owner with the most published models, timed (best of three).
create function pg_temp.best(account uuid) returns text language plpgsql as $$ declare t0 timestamptz; a numeric := 1e9; b numeric := 1e9; begin for i in 1..3 loop t0 := clock_timestamp(); perform public.designer_period(account); a := least(a, extract(epoch from clock_timestamp() - t0) * 1000); t0 := clock_timestamp(); perform public.designer_mine(account); b := least(b, extract(epoch from clock_timestamp() - t0) * 1000); end loop; return format('designer_period %s ms, designer_mine %s ms (best of three)', round(a, 1), round(b, 1)); end $$;
select (select count(*) from public.shared_models m where m.owner = b.owner and m.published) as models, pg_temp.best(b.owner) as "the owner with the most published models" from (select owner from public.shared_models where published and not barred group by owner order by count(*) desc limit 1) b;
-- The days, UTC: today, the last 30 from, the 30 before from, the 8 weeks from.
select d->>'today' as today, d->>'now_from' as now_from, d->>'before_from' as before_from, d->>'weeks_from' as weeks_from, d->>'views_from' as views_from, (d->>'today')::date = (now() at time zone 'UTC')::date as "today is the UTC day", (d->>'today')::date - (d->>'now_from')::date as "29", (d->>'now_from')::date - (d->>'before_from')::date as "30", (d->>'today')::date - (d->>'weeks_from')::date as "55" from (select public.designer_period('00000000-0000-4000-8000-000000000000') as d) x;
insert into auth.users (id, instance_id, aud, role, email) values ('00000000-0000-4000-8000-0000000000f1', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'period-ada@resend.dev'), ('00000000-0000-4000-8000-0000000000f2', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'period-bob@resend.dev'), ('00000000-0000-4000-8000-0000000000f3', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'period-cy@resend.dev');
select public.answer_age('00000000-0000-4000-8000-0000000000f1', true)->>'over_13' as ada, public.answer_age('00000000-0000-4000-8000-0000000000f2', true)->>'over_13' as bob, public.answer_age('00000000-0000-4000-8000-0000000000f3', true)->>'over_13' as cy;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000000f1', 'period-try-ada', 'Ada Try'), ('00000000-0000-4000-8000-0000000000f2', 'period-try-bob', 'Bob Try'), ('00000000-0000-4000-8000-0000000000f3', 'period-try-cy', 'Cy Try');
-- Ada's 50 models, shared 70 days ago (the last, A050, 20 days ago); one taken out and one unpublished, never counted. Bob's own model.
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) select 'PeriodA' || lpad(n::text, 3, '0'), '00000000-0000-4000-8000-0000000000f1', 'Period ' || n, 'Ada Try', 3, 100, n % 7 <> 0, case when n % 7 <> 0 then now() - interval '70 days' end, true, now() - case when n = 50 then interval '20 days' else interval '70 days' end, true from generate_series(1, 50) n;
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) values ('PeriodX001', '00000000-0000-4000-8000-0000000000f1', 'Period taken out', 'Ada Try', 3, 100, true, now() - interval '70 days', true, now() - interval '70 days', true), ('PeriodX002', '00000000-0000-4000-8000-0000000000f1', 'Period unpublished', 'Ada Try', 3, 100, false, null, true, now() - interval '70 days', false), ('PeriodB001', '00000000-0000-4000-8000-0000000000f2', 'Bob period', 'Bob Try', 3, 100, true, now() - interval '70 days', true, now() - interval '70 days', true);
update public.shared_models set barred = true where id = 'PeriodX001';
insert into public.share_versions (model, n, at, parts, bytes) select m.id, 1, m.created_at, 3, 100 from public.shared_models m where m.id like 'Period%';
-- Bob's remixes: of A001 ten days ago (counted), of A001 unpublished (not), of A002 45 days ago (counted, the 30 before).
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published, remixed_from) values ('PeriodR001', '00000000-0000-4000-8000-0000000000f2', 'Remix one', 'Bob Try', 3, 100, true, now() - interval '10 days', true, now() - interval '10 days', true, 'PeriodA001'), ('PeriodR002', '00000000-0000-4000-8000-0000000000f2', 'Remix two', 'Bob Try', 3, 100, false, null, true, now() - interval '3 days', false, 'PeriodA001'), ('PeriodR003', '00000000-0000-4000-8000-0000000000f2', 'Remix three', 'Bob Try', 3, 100, true, now() - interval '45 days', true, now() - interval '45 days', true, 'PeriodA002');
-- Views: 66 days of opens on each model (some days none), on the taken-out one too; in all, model_stats.views, more than the days kept.
insert into public.model_opens (model, day, opens) select 'PeriodA' || lpad(n::text, 3, '0'), (now() at time zone 'UTC')::date - d, (n * 7 + d * 3) % 11 from generate_series(1, 50) n, generate_series(0, 65) d where (n * 7 + d * 3) % 11 > 0;
insert into public.model_opens (model, day, opens) values ('PeriodX001', (now() at time zone 'UTC')::date, 40), ('PeriodB001', (now() at time zone 'UTC')::date, 40);
insert into public.model_stats (model, views) select o.model, sum(o.opens) + 100 from public.model_opens o where o.model like 'Period%' group by o.model on conflict (model) do update set views = excluded.views;
-- Builds: 600 devices over 66 days, and on A001 four at the edges: at the last 30 days' first instant (the last 30), a second before it and at the 30 before's first instant (the 30 before), a second before that (neither).
insert into public.model_builds (model, device, at) select 'PeriodA' || lpad((1 + k % 50)::text, 3, '0'), md5('period-build-' || k), now() - make_interval(hours => (k * 2) % 1580) from generate_series(1, 600) k;
insert into public.model_builds (model, device, at) values ('PeriodA001', md5('edge-1'), (((now() at time zone 'UTC')::date - 29)::timestamp at time zone 'UTC')), ('PeriodA001', md5('edge-2'), (((now() at time zone 'UTC')::date - 29)::timestamp at time zone 'UTC') - interval '1 second'), ('PeriodA001', md5('edge-3'), (((now() at time zone 'UTC')::date - 59)::timestamp at time zone 'UTC')), ('PeriodA001', md5('edge-4'), (((now() at time zone 'UTC')::date - 59)::timestamp at time zone 'UTC') - interval '1 second');
insert into public.model_stats (model, builds) select b.model, count(*) from public.model_builds b where b.model like 'Period%' group by b.model on conflict (model) do update set builds = excluded.builds;
select count(*) filter (where b.at >= (((now() at time zone 'UTC')::date - 29)::timestamp at time zone 'UTC')) as "A001 edge builds in the last 30 (1)", count(*) filter (where b.at >= (((now() at time zone 'UTC')::date - 59)::timestamp at time zone 'UTC') and b.at < (((now() at time zone 'UTC')::date - 29)::timestamp at time zone 'UTC')) as "in the 30 before (2)", count(*) filter (where b.at < (((now() at time zone 'UTC')::date - 59)::timestamp at time zone 'UTC')) as "before both (1)" from public.model_builds b where b.model = 'PeriodA001' and b.device in (md5('edge-1'), md5('edge-2'), md5('edge-3'), md5('edge-4'));
-- Likes: Bob's on each model n days ago, Cy's on each 3n mod 70 days ago, and Ada's own on A001 (not counted).
insert into public.model_likes (model, account, at) select 'PeriodA' || lpad(n::text, 3, '0'), '00000000-0000-4000-8000-0000000000f2', now() - make_interval(days => n) from generate_series(1, 50) n;
insert into public.model_likes (model, account, at) select 'PeriodA' || lpad(n::text, 3, '0'), '00000000-0000-4000-8000-0000000000f3', now() - make_interval(days => (n * 3) % 70, hours => n) from generate_series(1, 50) n;
insert into public.model_likes (model, account, at) values ('PeriodA001', '00000000-0000-4000-8000-0000000000f1', now());
-- Saves: Bob keeps A001-A020 in Saved, 2n days ago; his list holds A001 a day ago (he is counted once, at his Saved) and A030 five days ago; Cy's list holds A001 40 days ago and A002 today; Ada's own Saved and list hold A001 and A002 (not counted).
insert into public.model_favourites (model, account, at) select 'PeriodA' || lpad(n::text, 3, '0'), '00000000-0000-4000-8000-0000000000f2', now() - make_interval(days => 2 * n) from generate_series(1, 20) n;
insert into public.model_favourites (model, account, at) values ('PeriodA002', '00000000-0000-4000-8000-0000000000f1', now());
insert into public.model_collections (id, owner, name) values ('PeriodL001', '00000000-0000-4000-8000-0000000000f2', 'Bob keeps'), ('PeriodL002', '00000000-0000-4000-8000-0000000000f3', 'Cy keeps'), ('PeriodL003', '00000000-0000-4000-8000-0000000000f1', 'Ada keeps');
insert into public.model_collection_items (collection, model, at) values ('PeriodL001', 'PeriodA001', now() - interval '1 day'), ('PeriodL001', 'PeriodA030', now() - interval '5 days'), ('PeriodL002', 'PeriodA001', now() - interval '40 days'), ('PeriodL002', 'PeriodA002', now()), ('PeriodL003', 'PeriodA001', now());
-- Comments: Bob's on A001-A030, 2n days ago; Ada's own on A001 (not); Cy's on A003 hidden (not) and Bob's answer under it (not: its comment is not shown); Cy's on A004 removed (not); Bob's on A050 25 days ago, before its link's life began 20 days ago (not).
insert into public.model_comments (model, version, author, body, at) select 'PeriodA' || lpad(n::text, 3, '0'), 1, '00000000-0000-4000-8000-0000000000f2', 'Period try ' || n, now() - make_interval(days => 2 * n) from generate_series(1, 30) n;
insert into public.model_comments (model, version, author, body, at) values ('PeriodA001', 1, '00000000-0000-4000-8000-0000000000f1', 'Period try: thank you', now() - interval '1 day'), ('PeriodA003', 1, '00000000-0000-4000-8000-0000000000f3', 'Period try: hidden', now() - interval '3 days'), ('PeriodA004', 1, '00000000-0000-4000-8000-0000000000f3', 'Period try: removed', now() - interval '4 days'), ('PeriodA050', 1, '00000000-0000-4000-8000-0000000000f2', 'Period try: an earlier life', now() - interval '25 days');
insert into public.model_comments (model, version, author, body, at, parent) select 'PeriodA003', 1, '00000000-0000-4000-8000-0000000000f2', 'Period try: an answer', now() - interval '2 days', c.id from public.model_comments c where c.body = 'Period try: hidden';
update public.model_comments set hidden_at = now() where body = 'Period try: hidden';
update public.model_comments set removed_at = now(), removed_by = 'author' where body = 'Period try: removed';
-- What a count of each kind is, written plainly from the rows: [kind] of [model] on the UTC days [from] to [til].
create function pg_temp.direct(kind text, model text, f date, til date) returns bigint language plpgsql as $$ declare a timestamptz := f::timestamp at time zone 'UTC'; z timestamptz := (til + 1)::timestamp at time zone 'UTC'; owner uuid := (select m.owner from public.shared_models m where m.id = model); n bigint; begin if kind = 'views' then select coalesce(sum(o.opens), 0) into n from public.model_opens o where o.model = direct.model and o.day >= f and o.day <= til; elsif kind = 'builds' then select count(*) into n from public.model_builds b where b.model = direct.model and b.at >= a and b.at < z; elsif kind = 'likes' then select count(*) into n from public.model_likes l where l.model = direct.model and l.account <> owner and l.at >= a and l.at < z; elsif kind = 'saves' then select count(*) into n from (select x.account, min(x.at) as first from (select f2.account, f2.at from public.model_favourites f2 where f2.model = direct.model union all select c.owner, i.at from public.model_collection_items i join public.model_collections c on c.id = i.collection where i.model = direct.model) x where x.account <> owner group by x.account) y where y.first >= a and y.first < z; elsif kind = 'comments' then select coalesce((select s.recent from public.designer_said(array[direct.model], a) s), 0) - coalesce((select s.recent from public.designer_said(array[direct.model], z) s), 0) into n; elsif kind = 'remixes' then select count(*) into n from public.shared_models r where r.remixed_from = direct.model and r.published and r.created_at >= a and r.created_at < z; end if; return n; end $$;
create function pg_temp.ever(kind text, model text) returns bigint language plpgsql as $$ begin if kind = 'views' then return (select coalesce(s.views, 0) from public.model_stats s where s.model = ever.model); elsif kind = 'builds' then return (select coalesce(s.builds, 0) from public.model_stats s where s.model = ever.model); elsif kind = 'comments' then return coalesce((select s.comments from public.designer_said(array[ever.model]) s), 0); else return pg_temp.direct(kind, model, '1970-01-01', (now() at time zone 'UTC')::date + 1); end if; end $$;
create temp table period_said on commit drop as select m.key as model, k.key as kind, k.value as said from jsonb_each(public.designer_period('00000000-0000-4000-8000-0000000000f1')->'models') m, jsonb_each(m.value) k;
create temp table period_plain on commit drop as select p.model, p.kind, (p.said->>'now')::bigint as now, pg_temp.direct(p.kind, p.model, t.today - 29, t.today) as now_plain, (p.said->>'before')::bigint as before, pg_temp.direct(p.kind, p.model, t.today - 59, t.today - 30) as before_plain, (p.said->>'ever')::bigint as ever, pg_temp.ever(p.kind, p.model) as ever_plain, p.said->'weeks' as weeks, (select jsonb_agg(pg_temp.direct(p.kind, p.model, t.today - 55 + 7 * w, t.today - 49 + 7 * w) order by w) from generate_series(0, 7) w) as weeks_plain from period_said p, (select (now() at time zone 'UTC')::date as today) t;
-- Ada's answer: her 50 published models, none other (not the one taken out, not the unpublished one, not Bob's), each with all six kinds.
select count(distinct model) as models, count(*) as "model-kinds (300)", count(*) filter (where model in ('PeriodX001', 'PeriodX002', 'PeriodB001')) as "others' or not shown (0)", string_agg(distinct kind, ', ') as kinds from period_said;
-- Every number against its plain count: 50 models x 6 kinds x (the last 30, the 30 before, 8 weeks, in all) = 3,300 numbers; mismatches 0.
select count(*) * 11 as "numbers held", count(*) filter (where now <> now_plain) as "last 30 wrong", count(*) filter (where before <> before_plain) as "30 before wrong", count(*) filter (where weeks <> weeks_plain) as "weeks wrong", count(*) filter (where ever <> ever_plain) as "in all wrong" from period_plain;
-- What was counted, by kind: the sums, so nothing passes by counting nothing.
select kind, sum(now) as last_30, sum(before) as the_30_before, sum(ever) as in_all, sum((select sum(v::bigint) from jsonb_array_elements_text(weeks) v)) as in_the_8_weeks from period_plain group by kind order by kind;
-- A001 and A002 and A050 by hand: A001's builds include the edge ones; its likes Bob's (1 day ago) and Cy's (3 days ago), never Ada's; its saves Bob once (2 days ago: Saved before his list) and Cy (40 days ago), never Ada; A002's saves Bob (4 days ago) and Cy (today); its comments Bob's alone; its remixes 1 (the unpublished one not); A002's remix 45 days ago in the 30 before; A003's comments Bob's of 6 days ago only, A004's Bob's only, A050's none.
select model, kind, now, before, ever from period_plain where (model = 'PeriodA001' and kind in ('likes', 'saves', 'comments', 'remixes')) or (model = 'PeriodA002' and kind in ('saves', 'remixes')) or (model in ('PeriodA003', 'PeriodA004', 'PeriodA050') and kind = 'comments') order by model, kind;
-- Nobody else's: Bob's answer holds only his own (B001 and his two published remixes); no account none; an account with no models none.
select (select string_agg(k, ', ' order by k) from jsonb_object_keys(public.designer_period('00000000-0000-4000-8000-0000000000f2')->'models') k) as "Bob's", public.designer_period(null) is null as "no account", public.designer_period('00000000-0000-4000-8000-0000000000f3')->'models' = '{}'::jsonb as "Cy's none";
-- How long: Ada's 50 models, ten times; the middle and the slowest.
create function pg_temp.ten(account uuid) returns text language plpgsql as $$ declare t0 timestamptz; took numeric[] := '{}'; begin for i in 1..10 loop t0 := clock_timestamp(); perform public.designer_period(account); took := took || round(extract(epoch from clock_timestamp() - t0) * 1000, 1); end loop; return format('p50 %s ms, slowest %s ms of ten', (select percentile_disc(0.5) within group (order by x) from unnest(took) x), (select max(x) from unnest(took) x)); end $$;
select pg_temp.ten('00000000-0000-4000-8000-0000000000f1') as "Ada, 50 models";
select length(public.designer_period('00000000-0000-4000-8000-0000000000f1')::text) as "bytes of jsonb for 50 models";
-- Nobody but the server: the function the service role's alone, a definer with its search path set.
select p.proname, has_function_privilege('anon', p.oid, 'execute') as anon, has_function_privilege('authenticated', p.oid, 'execute') as authenticated, has_function_privilege('service_role', p.oid, 'execute') as service_role, p.prosecdef as definer, p.proconfig as config from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'designer_period'
